import{_ as e,c as i,o as l,ah as p,ao as a,ap as t}from"./chunks/framework.Dq2_gudl.js";const f=JSON.parse('{"title":"Pets in Heaven — 它们、天堂与你的悲伤","description":"写给失去毛孩子的你：从圣经看动物的永恒、神的看顾，以及如何在悲伤中被接住。四篇温柔的读物。","frontmatter":{"title":"Pets in Heaven — 它们、天堂与你的悲伤","description":"写给失去毛孩子的你：从圣经看动物的永恒、神的看顾，以及如何在悲伤中被接住。四篇温柔的读物。"},"headers":[],"relativePath":"zh/pets-in-heaven/index.md","filePath":"zh/pets-in-heaven/index.md"}'),n={name:"zh/pets-in-heaven/index.md"};function o(c,s,r,h,d,v){return l(),i("div",null,[...s[0]||(s[0]=[p('<div class="pl-quote"><p>「它走以后，我最想知道的只有一件事：它现在好不好？我们还会再见吗？」</p><p class="pl-quote-soft">圣经没有用一句话回答所有问题，但它给了我们足够的光，让我们在最黑的夜里仍能看见盼望。</p></div><section class="pl-section"><h2>写在开始之前</h2><p class="pl-lead">这里不是要你「快点走出来」的地方。这四篇文章，是写给还在想念它的你。</p><p>失去一只动物同伴，是一种很特别的悲伤。很多人会说「不过是一只狗」「再养一只就好了」——但你知道那不是真的。它记得你回家的脚步声，它在你最低潮的那一年一直靠在你的脚边，它的离开，带走的是每天早晨第一个迎接你的那个眼神。</p><p>圣经其实对动物说了很多话。神创造它们、喂养它们、与它们立约，把它们放在祂将要更新的世界里。这些经文不能证明「每一只宠物都在天堂」——圣经没有那样应许——但它们让我们看见一件温柔的事实：<strong>在神的计划里，动物从来不是可以被丢掉的配角。</strong></p><p>愿你在这里读到的，不只是经文，而是那位连麻雀都记得的神，如何也记得你的它。</p></section><section class="pl-section"><h2>四篇给你读的文章</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/zh/pets-in-heaven/will-i-see-my-pet-again">它会在那里吗？</a></h3><p>圣经里关于动物与天堂的盼望——受造之物一同等候得赎，新天新地里仍有动物的身影。</p><p class="pl-quote-soft">罗马书 8:19-22 · 以赛亚书 11:6-9 · 启示录 21:4-5</p></div><div class="pl-new-card"><h3><a href="/zh/pets-in-heaven/not-one-sparrow-forgotten">连一只麻雀，祂都记得</a></h3><p>它那么小，世界会记得它吗？耶稣说：一只麻雀掉在地上，天父都知道。</p><p class="pl-quote-soft">马太福音 10:29-31 · 诗篇 147:9 · 诗篇 36:6</p></div><div class="pl-new-card"><h3><a href="/zh/pets-in-heaven/rainbow-bridge-covenant">彩虹桥的那一端</a></h3><p>「彩虹桥」是很美的说法，而圣经里真的有彩虹——那是神与<em>一切活物</em>所立的永远的约。</p><p class="pl-quote-soft">创世记 9:9-13 · 以赛亚书 65:25 · 启示录 5:13</p></div><div class="pl-new-card"><h3><a href="/zh/pets-in-heaven/permission-to-grieve">允许自己悲伤</a></h3><p>你的眼泪，神都收在瓶子里。悲伤不是信心不足，而是爱还在继续。</p><p class="pl-quote-soft">诗篇 56:8 · 诗篇 34:18 · 马太福音 5:4</p></div></div></section><section class="pl-section"><h2>读的时候，你可以这样做</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>慢慢读，不必一次读完</h3><p>一次读一段就够了。如果某一节经文让你突然哭出来，那就停下来——那不是软弱，那是爱在流动。</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>把它的名字放进经文里</h3><p>读到「神喂养走兽」时，试着在心里换成它的名字。经文不是只给人的，神也这样看顾它。</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>读完后，对它说一句话</h3><p>你不需要写得漂亮。一句「我很想你」就足够了。想写得更多，PetLoss 里的引导式日记愿意陪你。</p></div></div></section><section class="pl-section"><h2>全部经文一览</h2><p class="pl-lead">这四篇文章提到的每一处圣经经文，都集中在这里，方便你反复读、慢慢查。</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/zh/pets-in-heaven/will-i-see-my-pet-again">它会在那里吗？</a></h3><ul class="pl-verse-list"><li>罗马书 8:19-22</li><li>以赛亚书 11:6-9</li><li>启示录 21:4-5</li><li>诗篇 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/zh/pets-in-heaven/not-one-sparrow-forgotten">连一只麻雀，祂都记得</a></h3><ul class="pl-verse-list"><li>马太福音 10:29-31</li><li>诗篇 147:9</li><li>诗篇 36:6</li><li>诗篇 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/zh/pets-in-heaven/rainbow-bridge-covenant">彩虹桥的那一端</a></h3><ul class="pl-verse-list"><li>创世记 9:9-13</li><li>以赛亚书 65:25</li><li>启示录 5:13</li><li>诗篇 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/zh/pets-in-heaven/permission-to-grieve">允许自己悲伤</a></h3><ul class="pl-verse-list"><li>诗篇 56:8</li><li>诗篇 34:18</li><li>诗篇 147:3</li><li>马太福音 5:4</li><li>约翰福音 11:35</li><li>启示录 21:4</li></ul></div></div></section><div class="pl-cta"><h2>愿你在这里，被轻轻接住。</h2><p>如果你想找一个地方安放它的照片、写下没来得及说的话，PetLoss 会安静地陪着你——无需帐号、不上传、完全离线。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下载</a><p class="pl-disclaimer">这些文章提供的是信仰反思与情感陪伴，不构成专业的医疗、心理或咨询建议。如果你长时间被悲伤压得无法生活，请寻求持证专业人士或本地支持专线的帮助。圣经引文采用英王钦定本（KJV）。</p></div><div class="pl-bible"><h3>让圣经的话继续陪你</h3><p>这四篇文章引用的经文都出自圣经。用《彩虹圣经》随时阅读神的话、设置每日经文小组件，在想念它的日子里仍有一盏灯。</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible 圣经小组件显示 2 Timothy 2:13" loading="lazy"><figcaption>每日经文放在主屏幕</figcaption></figure><figure><img src="'+t+'" alt="Rainbow Bible App 的「天堂里的毛孩」主题，显示 Matthew 10:29-31" loading="lazy"><figcaption>切换到「天堂里的毛孩」主题读经</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 获取《彩虹圣经》</a></div>',7)])])}const g=e(n,[["render",o]]);export{f as __pageData,g as default};
